"""Actual scanner omission of empty constructor/signal parameter containers."""
from pathlib import Path
import copy,hashlib,json,os,shlex,subprocess,sys,tempfile
import xml.etree.ElementTree as ET
ROOT=Path(__file__).resolve().parents[2]
def sha(path):return hashlib.sha256(path.read_bytes()).hexdigest()
def main(compiler_arg,output_arg):
	compiler=Path(compiler_arg).resolve();output=Path(output_arg).resolve();assert not output.is_relative_to(ROOT);output.mkdir(parents=True,exist_ok=True);work=Path(tempfile.mkdtemp(prefix='empty-gir-parameters-',dir=output));here=Path(__file__).resolve().parent;runtime=ROOT/'lib/runtime/interop';importer=ROOT/'tools/gir/import.py';profile=here/'empty-parameters-profile.json';sources=[Path(__file__).resolve(),*[here/('empty-parameters'+suffix) for suffix in ['.astra','-support.c','-client.c','-consumer.astra.in','-profile.json']],importer,importer.with_name('declarations.py'),runtime/'foreign-14.c',runtime/'gobject-signals-16.c',runtime/'gobject-signals-16.h'];receipt=dict(compiler_sha256=sha(compiler),sources={str(p.relative_to(ROOT)):sha(p) for p in sources},checks=[])
	def run(command,expected=0,contains='',env=None):
		assert sha(compiler)==receipt['compiler_sha256'];p=subprocess.run(list(map(str,command)),text=True,capture_output=True,cwd=work,timeout=120,env=dict(os.environ,G_DEBUG='fatal-warnings',PYTHONDONTWRITEBYTECODE='1',**(env or {})));receipt['checks'].append(dict(command=list(map(str,command)),exit=p.returncode,expected_exit=expected,stdout=p.stdout,stderr=p.stderr));(work/'checks.json').write_text(json.dumps(receipt,indent=2)+'\n');assert p.returncode==expected and contains in p.stdout+p.stderr,receipt['checks'][-1];return p.stdout
	flags=['-std=gnu11','-Wall','-Wextra','-Werror','-pthread'];includes=shlex.split(run(['pkg-config','--cflags','gobject-2.0']));libs=shlex.split(run(['pkg-config','--libs','gobject-2.0']));g='{http://www.gtk.org/introspection/core/1.0}';glib='{http://www.gtk.org/introspection/glib/1.0}'
	for level in '012':
		case=work/('O'+level);case.mkdir();source=here/'empty-parameters.astra';run([compiler,'-O'+level,'-c',source,'-o',case/'producer.o']);adapter=case/'adapter.c';adapter.write_text(run([compiler,'--emit-gobject-source',source]));header=case/'api.h';header.write_text(run([compiler,'--emit-gobject-header',source]));library=case/'libempty16.so';run(['cc',*flags,'-O'+level,'-fPIC','-shared','-Wl,-z,defs',*includes,adapter,here/'empty-parameters-support.c',runtime/'foreign-14.c',case/'producer.o',*libs,'-o',library]);gir=case/'Empty16-1.7.gir';run(['g-ir-scanner','--no-libtool','--namespace=Empty16','--nsversion=1.7','--include=GObject-2.0','--identifier-prefix=Empty16','--symbol-prefix=empty16','--library=empty16','--library-path='+str(case),'--c-include=api.h','--warn-all','--warn-error','--output='+str(gir),'--pkg=gobject-2.0','-I'+str(case),header],env=dict(LD_LIBRARY_PATH=str(case)));run(['g-ir-compiler',gir,'--output='+str(case/'Empty16-1.7.typelib')]);tree=ET.parse(gir);constructor=tree.find('.//'+g+'constructor[@name="new"]');signal=tree.find('.//'+glib+'signal[@name="tick"]');assert constructor is not None and signal is not None and constructor.find(g+'parameters') is None and signal.find(g+'parameters') is None;generated=case/'generated';run(['python3',importer,'--profile',profile,'--gir',gir,'--output',generated]);run(['python3',importer,'--profile',profile,'--gir',gir,'--verify',generated]);consumer=case/'consumer.astra';consumer.write_text((here/'empty-parameters-consumer.astra.in').read_text().replace('@BINDINGS@',(generated/'bindings.astra').read_text()));run([compiler,'-O'+level,'--vapi',generated/'bindings.vapi','-c',consumer,'-o',case/'consumer.o']);imports=case/'imports.c';imports.write_text(run([compiler,'--vapi',generated/'bindings.vapi','--emit-gobject-source',consumer]));client=case/'client';run(['cc',*flags,'-O'+level,*includes,'-I'+str(case),'-I'+str(generated),'-I'+str(runtime),imports,generated/'bindings.c',here/'empty-parameters-client.c',runtime/'gobject-signals-16.c',case/'consumer.o','-L'+str(case),'-Wl,-rpath,$ORIGIN','-lempty16',*libs,'-o',client]);run([client],contains='PASS zero-argument GIR constructor')
		if level in '02':run(['valgrind','--vgdb=no','--default-suppressions=no','--leak-check=full','--show-leak-kinds=definite,indirect,possible','--errors-for-leak-kinds=definite,indirect,possible','--error-exitcode=99',client],contains='ERROR SUMMARY: 0 errors')
		if level=='0':
			for label in ['empty-containers','duplicate-constructor','duplicate-signal','missing-receiver','signal-instance','unknown-list-attribute']:
				doc=copy.deepcopy(tree);ctor=doc.find('.//'+g+'constructor[@name="new"]');sig=doc.find('.//'+glib+'signal[@name="tick"]');method=doc.find('.//'+g+'method[@name="try_fire"]')
				if label=='empty-containers':ET.SubElement(ctor,g+'parameters');ET.SubElement(sig,g+'parameters')
				elif label=='duplicate-constructor':ET.SubElement(ctor,g+'parameters');ET.SubElement(ctor,g+'parameters')
				elif label=='duplicate-signal':ET.SubElement(sig,g+'parameters');ET.SubElement(sig,g+'parameters')
				elif label=='missing-receiver':method.remove(method.find(g+'parameters'))
				elif label=='signal-instance':ET.SubElement(ET.SubElement(sig,g+'parameters'),g+'instance-parameter')
				elif label=='unknown-list-attribute':ET.SubElement(ctor,g+'parameters',{'count':'0'})
				path=case/(label+'.gir');doc.write(path,encoding='utf8',xml_declaration=True);destination=case/label;run(['python3',importer,'--profile',profile,'--gir',path,'--output',destination],expected=0 if label=='empty-containers' else 1)
				if label=='empty-containers':assert all((generated/name).read_bytes()==(destination/name).read_bytes() for name in ['bindings.astra','bindings.vapi','bindings.h','bindings.c'])
				else:assert not destination.exists()
	receipt['status']='EMPTY_GIR_PARAMETERS_PASS';(work/'checks.json').write_text(json.dumps(receipt,indent=2)+'\n');print(json.dumps(dict(status=receipt['status'],commands=len(receipt['checks']),receipt=str(work/'checks.json'))))
if __name__=='__main__':main(*sys.argv[1:])
